);

import type { AdminClient } from "./v2_supabase.ts";
import { createAdminClient, optionalEnv } from "./v2_supabase.ts";
import { HttpError } from "./v2_http.ts";

export type AuthMode = "user" | "editor" | "secret";

export interface AuthContext {
  mode: AuthMode;
  userId: string | null;
  role: "user" | "editor" | "admin" | "service";
}

function getBearer(req: Request): string | null {
  const header = req.headers.get("authorization") ?? req.headers.get("Authorization");
  if (!header?.startsWith("Bearer ")) {
    return null;
  }
  const token = header.slice("Bearer ".length).trim();
  return token.length > 0 ? token : null;
}

function hasEditorRole(
  appMetadata: Record<string, unknown> | null | undefined,
): "editor" | "admin" | null {
  const role = typeof appMetadata?.role === "string" ? appMetadata.role : null;
  const facodiRole = typeof appMetadata?.facodi_role === "string" ? appMetadata.facodi_role : null;
  const roles = Array.isArray(appMetadata?.roles) ? appMetadata.roles : [];
  const normalized = [role, facodiRole, ...roles]
    .filter((value): value is string => typeof value === "string")
    .map((value) => value.toLowerCase());

  if (normalized.includes("admin")) {
    return "admin";
  }
  if (normalized.includes("editor")) {
    return "editor";
  }
  return null;
}

function validateSharedSecret(req: Request): boolean {
  const configured = optionalEnv("FACODI_WEBHOOK_SECRET");
  if (!configured) {
    return false;
  }
  const provided = req.headers.get("x-facodi-webhook-secret")?.trim();
  return Boolean(provided && provided === configured);
}

async function getProfileEditorRole(
  admin: AdminClient,
  userId: string,
): Promise<"user" | "editor" | "admin" | null> {
  const { data, error } = await admin
    .from("profiles")
    .select("role")
    .eq("id", userId)
    .maybeSingle<{ role: string | null }>();

  if (error) {
    return null;
  }

  const role = typeof data?.role === "string" ? data.role.toLowerCase() : null;
  if (role === "admin") {
    return "admin";
  }
  if (role === "editor") {
    return "editor";
  }
  if (role === "user") {
    return "user";
  }
  return null;
}

export async function requireEditorAuth(
  req: Request,
  admin: AdminClient = createAdminClient(),
): Promise<AuthContext> {
  const auth = await requireUserAuth(req, admin);

  if (auth.role !== "editor" && auth.role !== "admin") {
    throw new HttpError(
      403,
      "forbidden",
      "Editor or admin role required (app_metadata or profiles.role).",
    );
  }

  return {
    ...auth,
    role: auth.role,
  };
}

export async function requireUserAuth(
  req: Request,
  admin: AdminClient = createAdminClient(),
): Promise<AuthContext> {
  const token = getBearer(req);
  if (!token) {
    throw new HttpError(401, "unauthorized", "Missing bearer token.");
  }

  const { data, error } = await admin.auth.getUser(token);
  if (error || !data.user) {
    throw new HttpError(401, "unauthorized", "Invalid bearer token.");
  }

  const appMetadataRole = hasEditorRole((data.user.app_metadata ?? {}) as Record<string, unknown>);
  const profileRole = await getProfileEditorRole(admin, data.user.id);
  const role = appMetadataRole ?? profileRole ?? "user";

  return {
    mode: role === "editor" || role === "admin" ? "editor" : "user",
    userId: data.user.id,
    role,
  };
}

export async function requireInternalAuth(
  req: Request,
  admin: AdminClient = createAdminClient(),
): Promise<AuthContext> {
  if (validateSharedSecret(req)) {
    return {
      mode: "secret",
      userId: null,
      role: "service",
    };
  }

  return await requireEditorAuth(req, admin);
}

import { createClient, type SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.105.4";
import { HttpError } from "./v2_http.ts";

export type AdminClient = SupabaseClient;

export function env(name: string, fallbackNames: string[] = []): string {
  const names = [name, ...fallbackNames];
  for (const candidate of names) {
    const value = Deno.env.get(candidate)?.trim();
    if (value) {
      return value;
    }
  }
  throw new HttpError(500, "missing_environment", `Missing ${name} environment variable.`);
}

export function optionalEnv(name: string, fallbackNames: string[] = []): string | null {
  const names = [name, ...fallbackNames];
  for (const candidate of names) {
    const value = Deno.env.get(candidate)?.trim();
    if (value) {
      return value;
    }
  }
  return null;
}

export function createAdminClient(): AdminClient {
  const url = env("SUPABASE_URL");
  const serviceKey = env("SUPABASE_SERVICE_ROLE_KEY", ["SUPABASE_SECRET_KEY"]);

  return createClient(url, serviceKey, {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
    },
    global: {
      headers: {
        "x-application-name": "facodi-backend-v2",
      },
    },
  });
}

export function facodi(client: AdminClient) {
  const schema = optionalEnv("FACODI_DB_SCHEMA", ["SUPABASE_DB_SCHEMA"]) ?? "facodi";
  return client.schema(schema);
}

export function unwrap<T>(result: { data: T | null; error: { message: string } | null }): T {
  if (result.error) {
    throw new HttpError(500, "supabase_error", result.error.message);
  }
  if (result.data === null) {
    throw new HttpError(404, "not_found", "Expected row was not found.");
  }
  return result.data;
}

export function unwrapMaybe<T>(result: {
  data: T | null;
  error: { message: string } | null;
}): T | null {
  if (result.error) {
    throw new HttpError(500, "supabase_error", result.error.message);
  }
  return result.data;
}

export type JsonObject = Record<string, unknown>;

export class HttpError extends Error {
  status: number;
  code: string;
  details?: unknown;

  constructor(status: number, code: string, message?: string, details?: unknown) {
    super(message ?? code);
    this.status = status;
    this.code = code;
    this.details = details;
  }
}

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-facodi-webhook-secret",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

export function json(body: unknown, status = 200, headers: HeadersInit = {}): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders,
      "content-type": "application/json; charset=utf-8",
      ...headers,
    },
  });
}

export function ensureMethod(req: Request, methods: string | string[]): void {
  const allowed = Array.isArray(methods) ? methods : [methods];
  if (!allowed.includes(req.method)) {
    throw new HttpError(405, "method_not_allowed", `Allowed methods: ${allowed.join(", ")}`);
  }
}

export async function readJson<T>(req: Request): Promise<T> {
  try {
    return (await req.json()) as T;
  } catch (_error) {
    throw new HttpError(400, "invalid_json", "Request body must be valid JSON.");
  }
}

export async function optionalJson<T>(req: Request): Promise<T | null> {
  if (req.method === "GET") {
    return null;
  }
  const raw = await req.text();
  if (!raw.trim()) {
    return null;
  }
  try {
    return JSON.parse(raw) as T;
  } catch (_error) {
    throw new HttpError(400, "invalid_json", "Request body must be valid JSON.");
  }
}

export function errorResponse(error: unknown): Response {
  if (error instanceof HttpError) {
    return json(
      {
        success: false,
        error: error.code,
        message: error.message,
        details: error.details ?? undefined,
      },
      error.status,
    );
  }

  console.error(error);
  return json(
    {
      success: false,
      error: "unexpected_error",
      message: "Unexpected server error.",
    },
    500,
  );
}

export async function withHttp(
  req: Request,
  handler: () => Promise<Response> | Response,
): Promise<Response> {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    return await handler();
  } catch (error) {
    return errorResponse(error);
  }
}

export function assertString(value: unknown, code: string, message: string): string {
  if (typeof value !== "string" || !value.trim()) {
    throw new HttpError(400, code, message);
  }
  return value.trim();
}

import { HttpError } from "./v2_http.ts";
import type { AdminClient } from "./v2_supabase.ts";
import { facodi, unwrap } from "./v2_supabase.ts";
import { failJob, updateJob } from "./v2_jobs.ts";
import { runPipelineStage } from "./v2_video_pipeline_steps.ts";

export const DEFAULT_PIPELINE_STAGES = [
  "v2_fetch_youtube_metadata",
  "v2_extract_video_content",
  "v2_match_video_candidates",
  "v2_classify_video",
] as const;

export const PIPELINE_STAGES = [...DEFAULT_PIPELINE_STAGES, "v2_generate_embeddings"] as const;

export type PipelineStage = typeof PIPELINE_STAGES[number];

export interface ProcessPipelinePayload {
  job_id: string;
  stages?: string[];
  retry_failed?: boolean;
  request_id?: string;
}

export interface PipelineEventInput {
  job_id: string;
  event_type:
    | "pipeline_started"
    | "pipeline_succeeded"
    | "pipeline_failed"
    | "stage_started"
    | "stage_succeeded"
    | "stage_failed"
    | "retry_scheduled";
  step: string;
  status:
    | "queued"
    | "running"
    | "succeeded"
    | "failed"
    | "needs_review"
    | "cancelled"
    | "retrying";
  attempt?: number;
  request_id: string;
  error_code?: string | null;
  message?: string | null;
  metadata?: Record<string, unknown>;
}

export interface LoggedPipelineEvent extends PipelineEventInput {
  id?: string;
  requested_by?: string | null;
  created_at?: string;
}

interface StageError {
  status: number;
  code: string;
  message: string;
  details?: unknown;
}

const MAX_STAGE_ATTEMPTS = 3;

function isPipelineStage(value: string): value is PipelineStage {
  return (PIPELINE_STAGES as readonly string[]).includes(value);
}

function normalizeStages(stages: string[] | undefined): PipelineStage[] {
  if (!stages || stages.length === 0) {
    return [...DEFAULT_PIPELINE_STAGES];
  }
  const normalized = stages.map((stage) => stage.trim()).filter(Boolean);
  const invalid = normalized.filter((stage) => !isPipelineStage(stage));
  if (invalid.length > 0) {
    throw new HttpError(
      400,
      "invalid_pipeline_stage",
      `Invalid pipeline stage(s): ${invalid.join(", ")}`,
    );
  }
  return normalized as PipelineStage[];
}

function isRecoverableStageError(error: StageError): boolean {
  if (error.status === 408 || error.status === 429) {
    return true;
  }
  if (error.status >= 500) {
    return true;
  }
  return [
    "youtube_public_blocked",
    "supabase_error",
    "unexpected_error",
  ].includes(error.code);
}

function toStageError(error: unknown): StageError {
  if (error instanceof HttpError) {
    return {
      status: error.status,
      code: error.code,
      message: error.message,
      details: error.details,
    };
  }
  if (error instanceof Error) {
    return {
      status: 500,
      code: "unexpected_error",
      message: error.message,
    };
  }
  return {
    status: 500,
    code: "unexpected_error",
    message: "Unexpected pipeline error.",
  };
}

async function jobRequestedBy(
  admin: AdminClient,
  jobId: string,
): Promise<string | null> {
  const job = await facodi(admin)
    .from("analysis_jobs")
    .select("requested_by")
    .eq("id", jobId)
    .maybeSingle<{ requested_by: string | null }>();
  if (job.error) {
    throw new HttpError(500, "supabase_error", job.error.message);
  }
  return job.data?.requested_by ?? null;
}

export async function logJobEvent(
  admin: AdminClient,
  input: PipelineEventInput,
): Promise<LoggedPipelineEvent> {
  const requestedBy = await jobRequestedBy(admin, input.job_id);
  const row = {
    job_id: input.job_id,
    requested_by: requestedBy,
    event_type: input.event_type,
    step: input.step,
    status: input.status,
    attempt: input.attempt ?? 1,
    request_id: input.request_id,
    error_code: input.error_code ?? null,
    message: input.message ?? null,
    metadata: input.metadata ?? {},
  };
  const inserted = unwrap<{ id: string; created_at: string }>(
    await facodi(admin)
      .from("analysis_job_events")
      .insert(row)
      .select("id, created_at")
      .single(),
  );
  return {
    ...row,
    id: inserted.id,
    created_at: inserted.created_at,
  };
}

export async function listJobEvents(
  admin: AdminClient,
  jobId: string,
): Promise<LoggedPipelineEvent[]> {
  const result = await facodi(admin)
    .from("analysis_job_events")
    .select("*")
    .eq("job_id", jobId)
    .order("created_at", { ascending: true });
  if (result.error) {
    throw new HttpError(500, "supabase_error", result.error.message);
  }
  return (result.data ?? []) as LoggedPipelineEvent[];
}

async function runStageWithRetries(
  admin: AdminClient,
  stage: PipelineStage,
  jobId: string,
  requestId: string,
  events: LoggedPipelineEvent[],
): Promise<void> {
  for (let attempt = 1; attempt <= MAX_STAGE_ATTEMPTS; attempt += 1) {
    await updateJob(admin, jobId, {
      status: "running",
      current_step: stage,
      attempts: attempt,
      started_at: new Date().toISOString(),
    });
    events.push(await logJobEvent(admin, {
      job_id: jobId,
      event_type: "stage_started",
      step: stage,
      status: "running",
      attempt,
      request_id: requestId,
    }));

    try {
      const data = await runPipelineStage(admin, stage, { job_id: jobId });
      events.push(await logJobEvent(admin, {
        job_id: jobId,
        event_type: "stage_succeeded",
        step: stage,
        status: "succeeded",
        attempt,
        request_id: requestId,
        metadata: { response: data },
      }));
      return;
    } catch (error) {
      const stageError = toStageError(error);
      const recoverable = isRecoverableStageError(stageError);
      events.push(await logJobEvent(admin, {
        job_id: jobId,
        event_type: "stage_failed",
        step: stage,
        status: "failed",
        attempt,
        request_id: requestId,
        error_code: stageError.code,
        message: stageError.message,
        metadata: {
          recoverable,
          details: stageError.details ?? null,
        },
      }));

      if (recoverable && attempt < MAX_STAGE_ATTEMPTS) {
        events.push(await logJobEvent(admin, {
          job_id: jobId,
          event_type: "retry_scheduled",
          step: stage,
          status: "retrying",
          attempt: attempt + 1,
          request_id: requestId,
          error_code: stageError.code,
          message: stageError.message,
        }));
        continue;
      }
      throw new HttpError(stageError.status, stageError.code, stageError.message, stageError.details);
    }
  }
}

export async function processVideoPipeline(
  admin: AdminClient,
  payload: ProcessPipelinePayload,
): Promise<{
  success: boolean;
  job_id: string;
  status: string;
  current_step: string;
  classification_id: string | null;
  request_id: string;
  events: LoggedPipelineEvent[];
}> {
  if (!payload.job_id) {
    throw new HttpError(400, "missing_job_id", "Pipeline processing requires job_id.");
  }
  const requestId = payload.request_id ?? crypto.randomUUID();
  const stages = normalizeStages(payload.stages);
  const db = facodi(admin);
  const job = unwrap<Record<string, unknown>>(
    await db.from("analysis_jobs").select("*").eq("id", payload.job_id).maybeSingle(),
  );
  if (job.status === "failed" && payload.retry_failed !== true) {
    throw new HttpError(409, "job_failed_retry_required", "Set retry_failed=true to retry a failed job.");
  }

  const events: LoggedPipelineEvent[] = [];
  events.push(await logJobEvent(admin, {
    job_id: payload.job_id,
    event_type: "pipeline_started",
    step: "pipeline",
    status: "running",
    request_id: requestId,
    metadata: { stages },
  }));

  try {
    for (const stage of stages) {
      await runStageWithRetries(admin, stage, payload.job_id, requestId, events);
    }
  } catch (error) {
    const stageError = toStageError(error);
    await failJob(admin, payload.job_id, new HttpError(
      stageError.status,
      stageError.code,
      stageError.message,
      stageError.details,
    ));
    events.push(await logJobEvent(admin, {
      job_id: payload.job_id,
      event_type: "pipeline_failed",
      step: "pipeline",
      status: "failed",
      request_id: requestId,
      error_code: stageError.code,
      message: stageError.message,
      metadata: { details: stageError.details ?? null },
    }));
    throw error;
  }

  const [finalJob, classification] = await Promise.all([
    db.from("analysis_jobs").select("status,current_step").eq("id", payload.job_id).single(),
    db
      .from("video_classifications")
      .select("id")
      .eq("job_id", payload.job_id)
      .maybeSingle<{ id: string }>(),
  ]);
  if (finalJob.error) {
    throw new HttpError(500, "supabase_error", finalJob.error.message);
  }
  if (classification.error) {
    throw new HttpError(500, "supabase_error", classification.error.message);
  }

  events.push(await logJobEvent(admin, {
    job_id: payload.job_id,
    event_type: "pipeline_succeeded",
    step: "pipeline",
    status: finalJob.data.status as "succeeded" | "needs_review",
    request_id: requestId,
    metadata: {
      classification_id: classification.data?.id ?? null,
    },
  }));

  return {
    success: true,
    job_id: payload.job_id,
    status: String(finalJob.data.status),
    current_step: String(finalJob.data.current_step),
    classification_id: classification.data?.id ?? null,
    request_id: requestId,
    events,
  };
}

import type { AdminClient } from "./v2_supabase.ts";
import { facodi, unwrap, unwrapMaybe } from "./v2_supabase.ts";
import { HttpError } from "./v2_http.ts";

export interface JobContext {
  job: Record<string, unknown>;
  video: Record<string, unknown>;
}

export async function loadJobContext(
  admin: AdminClient,
  payload: { job_id?: string; video_id?: string; youtube_video_id?: string },
): Promise<JobContext> {
  const db = facodi(admin);
  let job: Record<string, unknown> | null = null;
  let video: Record<string, unknown> | null = null;

  if (payload.job_id) {
    job = unwrap<Record<string, unknown>>(
      await db.from("analysis_jobs").select("*").eq("id", payload.job_id).maybeSingle(),
    );
    const videoId = job.video_id as string | null;
    if (videoId) {
      video = unwrap<Record<string, unknown>>(
        await db.from("youtube_videos").select("*").eq("id", videoId).maybeSingle(),
      );
    }
  } else if (payload.video_id) {
    video = unwrap<Record<string, unknown>>(
      await db.from("youtube_videos").select("*").eq("id", payload.video_id).maybeSingle(),
    );
  } else if (payload.youtube_video_id) {
    video = unwrap<Record<string, unknown>>(
      await db
        .from("youtube_videos")
        .select("*")
        .eq("youtube_video_id", payload.youtube_video_id)
        .maybeSingle(),
    );
  }

  if (!video) {
    throw new HttpError(404, "video_not_found", "YouTube video was not found.");
  }

  if (!job) {
    job = unwrapMaybe<Record<string, unknown>>(
      await db
        .from("analysis_jobs")
        .select("*")
        .eq("video_id", video.id as string)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle(),
    );
  }

  if (!job) {
    job = unwrap<Record<string, unknown>>(
      await db
        .from("analysis_jobs")
        .insert({
          video_id: video.id,
          youtube_video_id: video.youtube_video_id,
          input_url: video.canonical_url,
          status: "queued",
          current_step: "created",
        })
        .select("*")
        .single(),
    );
  }

  return { job, video };
}

export async function updateJob(
  admin: AdminClient,
  jobId: string,
  patch: Record<string, unknown>,
): Promise<void> {
  const result = await facodi(admin).from("analysis_jobs").update(patch).eq("id", jobId);
  if (result.error) {
    throw new HttpError(500, "supabase_error", result.error.message);
  }
}

export async function failJob(
  admin: AdminClient,
  jobId: string | null | undefined,
  error: unknown,
): Promise<void> {
  if (!jobId) {
    return;
  }
  await updateJob(admin, jobId, {
    status: "failed",
    error_code: error instanceof HttpError ? error.code : "unexpected_error",
    error_message: error instanceof Error ? error.message : "Unexpected server error.",
    completed_at: new Date().toISOString(),
  });
}

import { HttpError } from "./v2_http.ts";
import { loadJobContext, updateJob } from "./v2_jobs.ts";
import {
  assignPlaylistDeterministically,
  type FacodiPlaylistCandidate,
} from "./v2_playlist_assignment.ts";
import { normalizeWhitespace, sha256Hex } from "./v2_text.ts";
